export function Typography({
  headingSize = {{headingSize}},
  bodySize = {{bodySize}},
  family = "{{family}}",
  headingWeight = "{{headingWeight}}",
}) {
  return (
    <div style={{ color: "#241430", width: 300, fontFamily: family }}>
      <h3 style={{ margin: "0 0 8px", fontSize: headingSize, fontWeight: Number(headingWeight) }}>A coordinated system</h3>
      <p style={{ margin: "0 0 12px", lineHeight: 1.6, fontSize: bodySize }}>
        Heading and body share one typeface and scale together, so the page reads as one voice rather than a pile of unrelated sizes.
      </p>
      <p style={{ margin: 0, font: "12px/1.4 system-ui, sans-serif", color: "#241430cc" }}>
        heading {headingSize}px/{headingWeight} &middot; body {bodySize}px
      </p>
    </div>
  );
}
